// ═══ DCL WITHOUT volatile — BROKEN! ═══
class Singleton {
    private static Singleton instance;  // NO volatile!
    private String config;

    private Singleton() {
        config = "loaded";  // step 2: constructor initializes fields
    }

    static Singleton getInstance() {
        if (instance == null) {           // check 1 (no lock)
            synchronized (Singleton.class) {
                if (instance == null) {   // check 2 (with lock)
                    instance = new Singleton();
                    // This line is 3 bytecode operations:
                    // 1. allocate memory (NEW)
                    // 2. call <init> constructor (INVOKESPECIAL)
                    // 3. assign to 'instance' (PUTSTATIC)
                    // CPU may REORDER to: 1 → 3 → 2!
                    // After 3: instance != null
                    // Before 2: config == null!
                }
            }
        }
        return instance;
    }
}
// Thread-A: executes 1→3→(hasn't done 2 yet)
// Thread-B: if (instance == null) → FALSE! (instance assigned at step 3!)
// Thread-B: return instance → config is NULL! → NPE!

// ═══ DCL WITH volatile — FIXED! ═══
class Singleton {
    private static volatile Singleton instance;  // VOLATILE!
    private String config;

    private Singleton() { config = "loaded"; }

    static Singleton getInstance() {
        if (instance == null) {
            synchronized (Singleton.class) {
                if (instance == null) {
                    instance = new Singleton();
                    // volatile write: STORE-STORE barrier before!
                    // Guarantees: constructor (step 2) completes BEFORE
                    // reference assignment (step 3) is visible to other threads!
                }
            }
        }
        return instance;  // volatile read: always sees fully constructed!
    }
}

// ═══ THREE LEVELS OF REORDERING ═══
// 1. COMPILER (javac): rarely reorders, but can optimize
// 2. JIT (HotSpot C2): aggressively reorders for CPU pipeline efficiency
// 3. CPU (hardware): out-of-order execution, store buffers, write combining
// All three respect AS-IF-SERIAL for the EXECUTING thread
// But OTHER threads see the reordered effects!

// ═══ MEMORY BARRIERS (what volatile inserts) ═══
// volatile write:
//   STORE-STORE barrier: all stores before this one complete first
//   STORE-LOAD barrier: this store visible before subsequent loads
// volatile read:
//   LOAD-LOAD barrier: this load completes before subsequent loads
//   LOAD-STORE barrier: this load completes before subsequent stores
// x86: only STORE-LOAD needs MFENCE (others are free — strong memory model)
// ARM/POWER: all barriers needed (weak memory model — more expensive!)
