// ─── File: src/test/java/com/bank/reorder/ReorderingDCLTest.java ───
package com.bank.reorder;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class ReorderingDCLTest {

    // ═══ SAFE DCL with volatile ═══
    static class PoolSingleton {
        private static volatile PoolSingleton instance;
        final String url;
        final int maxConnections;

        private PoolSingleton() {
            url = "jdbc:postgresql://localhost/bank";
            maxConnections = 20;
        }

        static PoolSingleton getInstance() {
            if (instance == null) {
                synchronized (PoolSingleton.class) {
                    if (instance == null) {
                        instance = new PoolSingleton();
                    }
                }
            }
            return instance;
        }
    }

    @Test
    void dclWithVolatile_alwaysFullyInitialized() throws InterruptedException {
        // Reset for test
        int threads = 100;
        CountDownLatch latch = new CountDownLatch(threads);
        AtomicInteger nullUrls = new AtomicInteger(0);

        for (int i = 0; i < threads; i++) {
            new Thread(() -> {
                PoolSingleton pool = PoolSingleton.getInstance();
                if (pool.url == null) nullUrls.incrementAndGet();
                if (pool.maxConnections != 20) nullUrls.incrementAndGet();
                latch.countDown();
            }).start();
        }
        latch.await();

        assertThat(nullUrls.get()).isEqualTo(0);  // ALWAYS fully initialized!
    }

    // ═══ Alternative: enum Singleton (no DCL needed!) ═══
    enum EnumSingleton {
        INSTANCE;
        final String url = "jdbc:postgresql://localhost/bank";
    }

    @Test
    void enumSingleton_simplestAndSafe() {
        assertThat(EnumSingleton.INSTANCE.url).isNotNull();
        // JVM guarantees enum initialization is thread-safe!
        // No volatile, no DCL, no reordering issues!
    }

    // ═══ Alternative: static holder (lazy, thread-safe) ═══
    static class HolderSingleton {
        private HolderSingleton() {}
        private static class Holder {
            static final HolderSingleton INSTANCE = new HolderSingleton();
        }
        static HolderSingleton getInstance() { return Holder.INSTANCE; }
    }

    @Test
    void holderPattern_lazyAndSafe() {
        assertThat(HolderSingleton.getInstance()).isNotNull();
        assertThat(HolderSingleton.getInstance()).isSameAs(HolderSingleton.getInstance());
        // Class loading guarantees thread safety! No volatile needed!
    }
}
